-- 396: service cards. A card is what Kita knows about one service of the catalogue (spec BLOCK-1-VISA
-- sections 3 and 4): the link to the law and the documents the service asks for. New tables only; no ALTER
-- on practices, practice_types or practice_required_documents. The cards are seeded from the reviewed
-- list of 2026-11-28 (sha256 6bfc6cfb4be5a93720c0c54b330aa1af4fb61606744f4b398a793300a9f0bba2), resolved
-- by practice_types.code only: a code that is absent from a database inserts nothing and does not fail.
-- visa_type_code is a logical link to visa_types.code, deliberately not a foreign key.
-- Staff-only text of the list (source_note, hold_reason, candidates_left_out) is not stored.
-- Nothing reads these tables until SERVICE_CARDS_SEEDING_CODES lists a code.

CREATE TABLE service_cards (
    practice_type_id integer PRIMARY KEY REFERENCES practice_types(id),
    block text NOT NULL CHECK (block IN ('visa', 'company', 'tax')),
    visa_type_code text,
    stage text NOT NULL DEFAULT 'new' CHECK (stage IN ('new', 'extension', 'conversion')),
    active boolean NOT NULL DEFAULT false,
    updated_by text,
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE service_card_documents (
    id bigserial PRIMARY KEY,
    practice_type_id integer NOT NULL REFERENCES service_cards(practice_type_id) ON DELETE CASCADE,
    document_type varchar(50) NOT NULL,
    label varchar(100) NOT NULL,
    client_text text NOT NULL,
    provider text NOT NULL CHECK (provider IN ('client', 'us', 'sponsor')),
    condition_text text,
    reuse text NOT NULL CHECK (reuse IN ('client_file', 'fresh')),
    source text NOT NULL CHECK (source IN ('official', 'house', 'request')),
    source_request_id bigint,
    sort_order integer NOT NULL,
    active boolean NOT NULL DEFAULT true,
    created_by text,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (practice_type_id, document_type)
);

-- Read-only consumers see the new tables; guarded as in 393.
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nuzantara_readonly') THEN
        GRANT SELECT ON TABLE service_cards, service_card_documents TO nuzantara_readonly;
    END IF;
END $$;

